"""Installed Atlas 0.2 import qualification of a JSON generated by real 0.1 code.

Uses Windows file picker and existing public GUI actions, then checks the
single Rust atlas-store-v1 data root. No test-only product commands or files
are written into the app store by this script.
"""
import json, os, subprocess, sys, time
from pathlib import Path

import pywinauto
from pywinauto import Application, Desktop, keyboard, mouse

sys.stdout.reconfigure(encoding="utf-8", errors="replace")
APP=Path(os.environ["ATLAS_INSTALLED_EXE"])
ARCHIVE=Path(os.environ["ATLAS_LEGACY_ARCHIVE"])
ROOT=Path(os.environ["LOCALAPPDATA"])/"ru.iwxa.atlas"/"atlas-store-v1"
OUT=Path("desktop/tests/visual-evidence")
OUT.mkdir(parents=True,exist_ok=True)
process=None
window=None
phase="startup"

def native_data():
    manifest=json.loads((ROOT/"head.json").read_text(encoding="utf-8"))
    projects=[]
    for item in manifest["projects"]:
        block=ROOT/"blocks"/(item["sha256"]+".json")
        p=json.loads(block.read_text(encoding="utf-8"))
        assert item["id"]==p["id"], "Block and index ID mismatch"
        projects.append(p)
    return manifest,projects

def shot(name):
    try:
        from PIL import ImageGrab
        ImageGrab.grab().save(OUT/("installed-import-"+name+".png"))
        print("ATLAS_IMPORT_GUI_SCREENSHOT "+name,flush=True)
    except Exception as exc:
        print("ATLAS_IMPORT_SCREENSHOT_UNAVAILABLE "+str(exc),flush=True)

def find_button(title,timeout=30):
    until=time.monotonic()+timeout
    while time.monotonic()<until:
        try:
            for child in window.descendants():
                if child.element_info.control_type=="Button" and child.element_info.name.strip()==title:
                    return child
        except Exception:
            pass
        time.sleep(.4)
    raise RuntimeError("UIA button unavailable: "+title)

def ui_diagnostic(label):
    shot(label)
    try:
        controls=[]
        for element in window.descendants():
            name=str(element.element_info.name or "").strip()
            kind=str(element.element_info.control_type)
            if name and kind in ("Button","Text","Edit"):
                controls.append({"kind":kind,"name":name[:90],
                    "enabled":bool(element.is_enabled()),
                    "visible":bool(element.is_visible())})
            if len(controls)>=90:
                break
        print("ATLAS_IMPORT_UI_STATE "+label+" "+json.dumps(controls,ensure_ascii=False),flush=True)
    except Exception as exc:
        print("ATLAS_IMPORT_UI_DIAGNOSTIC_ERROR "+str(exc),flush=True)
    try:
        manifest,projects=native_data()
        print("ATLAS_IMPORT_NATIVE_STATE "+label+" generation="+str(manifest.get("generation"))+
              " revision="+str(manifest.get("revision"))+
              " projects="+str(len(projects))+
              " names="+repr([p.get("name") for p in projects[:5]]),flush=True)
    except Exception as exc:
        print("ATLAS_IMPORT_NATIVE_DIAGNOSTIC_ERROR "+str(exc),flush=True)

def click_button(title,timeout=35):
    deadline=time.monotonic()+timeout
    last=None
    while time.monotonic()<deadline:
        try:
            control=find_button(title,timeout=2)
            if control.is_visible() and control.is_enabled():
                control.click_input()
                print("ATLAS_IMPORT_VISIBLE_BUTTON_CLICK "+title,flush=True)
                time.sleep(.45)
                return
            last="Button found but not enabled/visible"
        except Exception as exc:
            last=str(exc)[:140]
        time.sleep(.4)
    ui_diagnostic("button-unavailable")
    raise RuntimeError("Installed GUI button not actionable: "+title+" / "+str(last))


def import_preview_active():
    # Re-query current UIA nodes after every React render. A click attempt is
    # not activation until the modal is gone and Save is enabled.
    nodes=window.descendants()
    preview=next((n for n in nodes if n.element_info.control_type=="Button"
                  and n.element_info.name.strip()=="Заменить портфель в черновике"),None)
    save=next((n for n in nodes if n.element_info.control_type=="Button"
               and n.element_info.name.strip()=="Сохранить"),None)
    return preview,save

def confirm_import_draft():
    confirmation=find_button("Заменить портфель в черновике",timeout=25)
    if not confirmation.is_visible() or not confirmation.is_enabled():
        ui_diagnostic("confirm-outside-viewport")
        raise RuntimeError("Import confirmation is offscreen or disabled")
    try:
        window.set_focus()
        confirmation.set_focus()
        keyboard.send_keys("{ENTER}")
        print("ATLAS_IMPORT_CONFIRM_KEYBOARD_ENTER",flush=True)
    except Exception as exc:
        print("ATLAS_IMPORT_CONFIRM_FOCUS_FALLBACK "+repr(exc),flush=True)
        confirmation.click_input()
        print("ATLAS_IMPORT_CONFIRM_POINTER_FALLBACK",flush=True)
    for attempt in range(36):
        try:
            preview,save=import_preview_active()
            if preview is None and save is not None and save.is_enabled():
                print("ATLAS_IMPORT_CONFIRMED_DRAFT_READY_PASS",flush=True)
                return
            # A second input method is attempted only when the preview
            # remains open. No repeat is sent after the draft changes.
            if attempt==18 and preview is not None:
                print("ATLAS_IMPORT_CONFIRM_FIRST_ATTEMPT_NOT_APPLIED",flush=True)
                if preview.is_enabled() and preview.is_visible():
                    preview.click_input()
                    print("ATLAS_IMPORT_CONFIRM_POINTER_RETRY",flush=True)
        except Exception as exc:
            print("ATLAS_IMPORT_CONFIRM_PROBE "+repr(exc)[:160],flush=True)
        time.sleep(.4)
    ui_diagnostic("confirm-no-draft")
    raise RuntimeError("Import confirmation did not change React draft; inspect UI alert and button state")

def choose_json_file(path,save=False):
    # Hosted Windows may have unrelated #32770 dialogs (e.g. System
    # Properties). Only the actual Atlas picker title is acceptable.
    # The genuine title works with both Win32 and UIA backends.
    expected_title="Сохранить резервную копию Atlas JSON" if save else "Открыть архив Atlas JSON"
    # Enumerate actual top-level windows and record diagnostics.
    deadline=time.monotonic()+25
    seen=[]
    while time.monotonic()<deadline:
        matches=[]
        seen=[]
        for backend in ("win32","uia"):
            try:
                for item in Desktop(backend=backend).windows():
                    try:
                        if not item.is_visible():
                            continue
                        name=item.window_text()
                        kind=item.class_name()
                        seen.append(backend+":"+kind+":"+name[:100])
                        if name.strip()==expected_title and kind=="#32770":
                            matches.append((backend,item))
                    except Exception:
                        pass
            except Exception as exc:
                seen.append(backend+" error="+str(exc)[:100])
        if matches:
            backend,dialog=matches[0]
            print("ATLAS_IMPORT_PICKER_FOUND backend="+backend+" class="+str(dialog.class_name())+
                  " title="+repr(dialog.window_text()),flush=True)
            dialog.set_focus()
            keyboard.send_keys("%n")
            # Save As pre-populates atlas-backup.json. Replace that entire
            # suggested filename, rather than appending to it.
            keyboard.send_keys("^a")
            keyboard.send_keys(str(path),with_spaces=True)
            keyboard.send_keys("{ENTER}")
            return
        time.sleep(.4)
    raise RuntimeError("No Atlas JSON picker with title "+repr(expected_title)+
                       "; windows="+repr(seen[:35]))


def activate_button(title,timeout=25):
    element=find_button(title,timeout=timeout)
    try:
        window.set_focus()
        element.set_focus()
        keyboard.send_keys("{ENTER}")
        print("ATLAS_GUI_ACTION_ENTER "+title,flush=True)
    except Exception as exc:
        if not element.is_visible() or not element.is_enabled():
            ui_diagnostic("unreachable-"+title[:24])
            raise RuntimeError("Control not reachable: "+title) from exc
        element.click_input()
        print("ATLAS_GUI_ACTION_CLICK "+title,flush=True)
    time.sleep(.5)

def find_edit(label,timeout=18):
    end=time.monotonic()+timeout
    while time.monotonic()<end:
        try:
            for element in window.descendants():
                # HTML input[type=number] is exposed as Spinner/SpinButton
                # by WebView2 UI Automation, unlike text inputs (Edit).
                if (element.element_info.control_type in ("Edit","Spinner","SpinButton")
                    and element.element_info.name.strip()==label):
                    return element
        except Exception:
            pass
        time.sleep(.3)
    options=[]
    for element in window.descendants():
        try:
            name=(element.element_info.name or "").strip()
            if label in name:
                options.append((element.element_info.control_type,name,element.is_visible(),element.is_enabled()))
        except Exception:
            pass
    print("ATLAS_GUI_FIELD_CONTROL_CANDIDATES "+repr(options[:15]),flush=True)
    ui_diagnostic("missing-editor-field")
    raise RuntimeError("GUI form field not accessible: "+label)

def enter_editor_value(label,value):
    element=find_edit(label)
    element.set_focus()
    keyboard.send_keys("^a")
    keyboard.send_keys(value,with_spaces=True)
    time.sleep(.2)
    print("ATLAS_GUI_FIELD_FILLED "+label,flush=True)

def submit_editor():
    keyboard.send_keys("^{ENTER}")
    end=time.monotonic()+16
    while time.monotonic()<end:
        try:
            if not any(x.element_info.control_type=="Button" and
                       x.element_info.name.strip()=="Применить к черновику"
                       for x in window.descendants()):
                print("ATLAS_GUI_EDITOR_APPLIED_PASS",flush=True)
                return
        except Exception:
            pass
        time.sleep(.3)
    ui_diagnostic("editor-not-applied")
    raise RuntimeError("Editor submission has not closed the form")

def save_and_verify(predicate,label,old_gen):
    activate_button("Сохранить")
    deadline=time.monotonic()+40
    while time.monotonic()<deadline:
        try:
            h,projects=native_data()
            if h["generation"]!=old_gen and predicate(h,projects):
                print(label+" generation="+h["generation"],flush=True)
                return h,projects
        except (OSError,ValueError,KeyError,AssertionError):
            pass
        time.sleep(.35)
    ui_diagnostic("no-commit-"+label[:20])
    raise RuntimeError("GUI Ctrl+S/save did not persist: "+label)

def boot():
    global process,window
    process=subprocess.Popen([str(APP)],env={**os.environ,"ATLAS_CI_RENDERER_PROBE":"1"})
    ui=Application(backend="uia")
    deadline=time.monotonic()+45
    while time.monotonic()<deadline:
        if process.poll() is not None:
            raise RuntimeError("Installed app exited before import: "+str(process.returncode))
        try:
            ui.connect(process=process.pid,timeout=2)
            win=ui.top_window()
            if win.exists(timeout=1) and win.is_visible():
                window=win
                find_button("Открыть JSON",timeout=25)
                return
        except Exception:
            pass
        time.sleep(.5)
    raise RuntimeError("Installed Atlas window inaccessible to real GUI import")

def stop():
    global process,window
    if process and process.poll() is None:
        try:
            window.set_focus()
            keyboard.send_keys("%{F4}")
            process.wait(timeout=9)
        except Exception:
            process.kill()
            process.wait(timeout=10)
            raise RuntimeError("Installed app did not close cleanly after import test")
    window=None
    process=None

try:
    if not ARCHIVE.is_file():
        raise RuntimeError("Genuine release 0.1 archive not found")
    baseline,original=native_data()
    assert len(original)==2, "Existing installed GUI lifecycle must finish with two projects"
    assert any(p["name"]=="AtlasGUIFirstSave" for p in original)
    legacy=json.loads(ARCHIVE.read_text(encoding="utf-8"))
    assert len(legacy["projects"])==2
    phase="open-file-dialog"
    boot()
    click_button("Открыть JSON")
    choose_json_file(ARCHIVE)
    phase="human-import-preview"
    confirm=find_button("Заменить портфель в черновике",timeout=30)
    # The actual installed viewport must expose the confirmation, rather
    # than leaving an enabled button out of sight under a tall preview.
    deadline=time.monotonic()+8
    while time.monotonic()<deadline and (not confirm.is_visible() or not confirm.is_enabled()):
        time.sleep(.3)
        confirm=find_button("Заменить портфель в черновике",timeout=2)
    if not confirm.is_visible() or not confirm.is_enabled():
        ui_diagnostic("confirm-outside-viewport")
        raise RuntimeError("Legacy import confirmation cannot be reached in the installed viewport")
    print("ATLAS_IMPORT_CONFIRM_VISIBLE_PASS",flush=True)
    shot("preview")
    confirm_import_draft()
    # Approval changes the React draft only; persistence still needs Save.
    after_preview,still_on_disk=native_data()
    assert after_preview["generation"]==baseline["generation"]
    assert sorted(p["id"] for p in still_on_disk)==sorted(p["id"] for p in original)
    print("ATLAS_IMPORT_PRE_SAVE_NATIVE_UNCHANGED_PASS",flush=True)
    phase="save-imported-draft"
    # Async native generation guard and React transition must finish before
    # Save becomes enabled. Never click a disabled background toolbar action.
    click_button("Сохранить",timeout=35)
    deadline=time.monotonic()+40
    imported=None
    while time.monotonic()<deadline:
        try:
            current,projects=native_data()
            if current["generation"]!=baseline["generation"] and sorted(p["id"] for p in projects)==sorted(p["id"] for p in legacy["projects"]):
                imported=(current,projects)
                break
        except (OSError,ValueError,KeyError):
            pass
        time.sleep(.35)
    if imported is None:
        ui_diagnostic("legacy-save-no-readback")
        raise RuntimeError("The imported legacy JSON was not committed through the installed GUI")
    current,projects=imported
    first=next(p for p in projects if p["name"]=="ATLAS_LEGACY_01_RESEARCH")
    assert len(first["items"])==2 and len(first["dependencies"])==1
    assert len(first["findings"])==1 and len(first["decisions"])==1
    assert first["findings"][0]["revision"]=="a"*40
    assert current["revision"]>baseline["revision"]
    assert any(baseline["generation"] in p.name for p in (ROOT/"history").iterdir()), "Previous generation not retained"
    print("ATLAS_INSTALLED_LEGACY_01_IMPORT_COMMIT_READBACK_PASS",flush=True)
    stop()
    phase="restart-imported-portfolio"
    boot()
    reread,after=native_data()
    assert reread["generation"]==current["generation"]
    assert sorted(p["id"] for p in after)==sorted(p["id"] for p in legacy["projects"])
    shot("reopened")
    print("ATLAS_INSTALLED_LEGACY_01_IMPORT_RESTART_PASS",flush=True)
    # Large GUI scenario runs ONLY after the authentic 0.1 installed
    # import has committed, survived graceful close and restarted.
    stop()
    phase="large-portfolio-open"
    r5_path=Path(os.environ["ATLAS_R5_PORTFOLIO_JSON"])
    expected=json.loads(r5_path.read_text(encoding="utf-8-sig"))
    assert len(expected["projects"])==120
    expected_ids=sorted(p["id"] for p in expected["projects"])
    expected_works=sum(len(p["items"]) for p in expected["projects"])
    expected_links=sum(len(p["dependencies"]) for p in expected["projects"])
    assert expected_works==1200 and expected_links==300
    boot()
    t0=time.monotonic()
    click_button("Открыть JSON")
    choose_json_file(r5_path)
    phase="large-portfolio-preview"
    confirmation=find_button("Заменить портфель в черновике",timeout=35)
    assert confirmation.is_visible() and confirmation.is_enabled(), "Large portfolio confirmation outside viewport"
    preview_ms=round((time.monotonic()-t0)*1000)
    shot("large-preview")
    confirm_import_draft()
    phase="large-portfolio-save"
    click_button("Сохранить",timeout=45)
    deadline=time.monotonic()+60
    large=None
    while time.monotonic()<deadline:
        try:
            opened,actual=native_data()
            if opened["generation"]!=reread["generation"] and sorted(p["id"] for p in actual)==expected_ids:
                large=(opened,actual)
                break
        except (OSError,ValueError,KeyError):
            pass
        time.sleep(.4)
    if large is None:
        ui_diagnostic("r5-save-no-readback")
        raise RuntimeError("Large GUI import was not committed to native Atlas store")
    large_head,actual=large
    assert sum(len(p["items"]) for p in actual)==expected_works
    assert sum(len(p["dependencies"]) for p in actual)==expected_links
    assert large_head["revision"]>reread["revision"]
    gui_total_ms=round((time.monotonic()-t0)*1000)
    print("ATLAS_INSTALLED_R5_GUI_IMPORT_READBACK_PASS projects=120 works=1200 workLinks=300 previewMs="+str(preview_ms)+" totalMs="+str(gui_total_ms),flush=True)
    stop()
    phase="large-portfolio-restart"
    t0=time.monotonic()
    boot()
    reopened,actual=native_data()
    assert reopened["generation"]==large_head["generation"]
    assert sorted(p["id"] for p in actual)==expected_ids
    assert sum(len(p["items"]) for p in actual)==expected_works
    assert sum(len(p["dependencies"]) for p in actual)==expected_links
    boot_ms=round((time.monotonic()-t0)*1000)
    shot("large-reopened")
    print("ATLAS_INSTALLED_R5_GUI_REOPEN_PASS projects=120 works=1200 startupMs="+str(boot_ms),flush=True)
    # A genuine external backup must be produced by the installed GUI's
    # system save picker. It must be a readable atlas.project/1 snapshot.
    phase="gui-backup-export"
    # On hosted Windows tempfile.gettempdir() may use 8.3 paths such as
    # RUNNER~1. pywinauto.send_keys treats ~ as Enter and would accidentally
    # save C:\\Users\\RUNNER.json instead of the requested file.
    # RUNNER_TEMP is the existing full-length CI output directory, shared
    # with the authentic 0.1 and 120-project JSON fixtures.
    exported=Path(os.environ["RUNNER_TEMP"])/("atlas-0-2-gui-backup-"+str(os.getpid())+".json")
    assert not any(char in str(exported) for char in "~+^%{}"), "Unsafe SendKeys path; use literal input"
    assert not exported.exists()
    click_button("Резервная копия")
    choose_json_file(exported,save=True)
    deadline=time.monotonic()+20
    while not exported.is_file() and time.monotonic()<deadline:
        time.sleep(.3)
    if not exported.is_file():
        # Distinguish a Windows Save As driver problem from a Tauri export
        # error. Surface the actual UI message, visible dialogs and nearby
        # filenames instead of incorrectly blaming the native store.
        recent=[str(p) for p in exported.parent.glob("atlas*backup*.json")]
        print("ATLAS_BACKUP_EXPECTED_PATH "+str(exported),flush=True)
        print("ATLAS_BACKUP_PRESENT_CANDIDATES "+repr(recent[:20]),flush=True)
        seen=[]
        for backend in ("win32","uia"):
            for dialog in Desktop(backend=backend).windows():
                if dialog.is_visible():
                    seen.append(backend+":"+dialog.class_name()+":"+dialog.window_text()[:120])
        print("ATLAS_BACKUP_VISIBLE_WINDOWS "+repr(seen[:40]),flush=True)
        ui_diagnostic("backup-export-missing")
        raise RuntimeError("Installed GUI did not create backup at the selected path")
    print("ATLAS_BACKUP_PATH_READBACK "+str(exported),flush=True)
    backup=json.loads(exported.read_text(encoding="utf-8-sig"))
    assert sorted(p["id"] for p in backup["projects"])==expected_ids
    assert sum(len(p["items"]) for p in backup["projects"])==expected_works
    assert sum(len(p["dependencies"]) for p in backup["projects"])==expected_links
    unchanged,_=native_data()
    assert unchanged["generation"]==large_head["generation"], "Backup unexpectedly changed native generation"
    print("ATLAS_INSTALLED_GUI_BACKUP_EXPORT_PASS projects=120 works=1200",flush=True)

    # Native history must offer the prior real 0.1 portfolio and restore it
    # by an explicit user selection, then preserve the R5 head in history.
    phase="gui-history-list"
    click_button("Версии на диске")
    selection=find_button("Выбрать редакцию",timeout=25)
    if not selection.is_visible() or not selection.is_enabled():
        ui_diagnostic("history-selection-unavailable")
        raise RuntimeError("History entry selection inaccessible in installed GUI")
    selection.set_focus()
    keyboard.send_keys("{ENTER}")
    print("ATLAS_INSTALLED_HISTORY_SELECTION_VISIBLE_PASS",flush=True)
    phase="gui-history-confirm"
    click_button("Восстановить выбранную редакцию",timeout=25)
    deadline=time.monotonic()+45
    historical=None
    legacy_ids=sorted(p["id"] for p in legacy["projects"])
    while time.monotonic()<deadline:
        try:
            h,p=native_data()
            if h["generation"]!=large_head["generation"] and sorted(x["id"] for x in p)==legacy_ids:
                historical=(h,p)
                break
        except (OSError,ValueError,KeyError):
            pass
        time.sleep(.35)
    if historical is None:
        ui_diagnostic("history-restore-no-readback")
        raise RuntimeError("Installed history action did not restore the previous legacy portfolio")
    history_head,old_projects=historical
    assert history_head["revision"]>large_head["revision"]
    assert any(large_head["generation"] in path.name for path in (ROOT/"history").glob("*.json"))
    assert any(p["name"]=="ATLAS_LEGACY_01_RESEARCH" for p in old_projects)
    print("ATLAS_INSTALLED_GUI_HISTORY_RESTORE_READBACK_PASS projects=2",flush=True)
    stop()
    phase="gui-history-restart"
    boot()
    restored_after,again=native_data()
    assert restored_after["generation"]==history_head["generation"]
    assert sorted(p["id"] for p in again)==legacy_ids
    shot("history-restored-reopened")
    print("ATLAS_INSTALLED_GUI_HISTORY_RESTART_PASS projects=2",flush=True)
    stop()

    # User route G11: importing a synthetic pre-observation is only the setup.
    # Subsequent review, human decision, proposal, approval and amendment
    # MUST be entered through actual installed WebView2 controls.
    phase="gui-full-route-import"
    route_file=Path(os.environ["ATLAS_GUI_ROUTE_JSON"])
    baseline_route=json.loads(route_file.read_text(encoding="utf-8-sig"))
    assert len(baseline_route["projects"])==2
    boot()
    activate_button("Открыть JSON")
    choose_json_file(route_file)
    confirm_import_draft()
    before_route,_=native_data()
    route_ids=sorted(x["id"] for x in baseline_route["projects"])
    route_head,stored=save_and_verify(
        lambda h,projects: sorted(p["id"] for p in projects)==route_ids,
        "ATLAS_GUI_ROUTE_IMPORT_READBACK_PASS",before_route["generation"])
    root_id=baseline_route["projects"][0]["id"]
    source_initial=next(p for p in stored if p["id"]==root_id)
    assert len(source_initial["findings"])==1
    assert source_initial["items"][0]["estimateDays"]==2

    phase="gui-full-route-recheck"
    activate_button("ATLAS_RELEASE_02_UPSTREAM")
    activate_button("План / факт")
    activate_button("Повторно проверить")
    enter_editor_value("Что именно перепроверено на этой ревизии?","Retested the upstream release on the latest branch")
    submit_editor()
    after_recheck,stored=save_and_verify(lambda h,projects:
        len(next(p for p in projects if p["id"]==root_id)["findings"])==2,
        "ATLAS_GUI_ROUTE_SHA_RECHECK_PASS",route_head["generation"])
    checked=next(p for p in stored if p["id"]==root_id)
    assert checked["findings"][-1]["revision"]=="b"*40
    assert checked["findings"][-1]["reviewOfFindingId"]==source_initial["findings"][0]["id"]

    phase="gui-full-route-decision"
    activate_button("▦ Портфель проектов 2")
    activate_button("Рассмотреть план")
    control=None
    for x in window.descendants():
        if x.element_info.control_type=="ComboBox" and x.element_info.name.strip()=="Что делать с текущим планом?":
            control=x
            break
    if control is None:
        ui_diagnostic("plan-decision-selector-missing")
        raise RuntimeError("Human plan-decision control missing")
    control.set_focus()
    keyboard.send_keys("{HOME}{DOWN}")
    enter_editor_value("Основание решения (не менее восьми символов)",
                       "Fresh source revision requires an explicit release plan update")
    submit_editor()
    after_decision,stored=save_and_verify(lambda h,projects: any(
        d.get("kind")=="plan_review" and d.get("outcome")=="revise"
        for d in next(p for p in projects if p["id"]==root_id)["decisions"]),
        "ATLAS_GUI_ROUTE_HUMAN_DECISION_PASS",after_recheck["generation"])

    phase="gui-full-route-proposal"
    activate_button("▦ Портфель проектов 2")
    activate_button("Предложить изменение")
    enter_editor_value("Что изменить в плане?","ATLAS_RELEASE_02_REVISE")
    enter_editor_value("Предлагаемое изменение и причины",
                       "Extend the upstream validation work for current SHA")
    submit_editor()
    after_proposal,stored=save_and_verify(lambda h,projects: any(
        x["title"]=="ATLAS_RELEASE_02_REVISE"
        for x in next(p for p in projects if p["id"]==root_id)["changes"]),
        "ATLAS_GUI_ROUTE_PROPOSAL_PASS",after_decision["generation"])
    proposed=next(x for x in next(p for p in stored if p["id"]==root_id)["changes"]
                  if x["title"]=="ATLAS_RELEASE_02_REVISE")
    assert proposed["status"]=="proposed"

    phase="gui-full-route-amendment"
    activate_button("Изменить работу")
    enter_editor_value("Новая оценка, календарных дней","6")
    submit_editor()
    after_amend,stored=save_and_verify(lambda h,projects: any(
        c.get("planAmendments") and
        c["id"]==proposed["id"]
        for c in next(p for p in projects if p["id"]==root_id)["changes"]),
        "ATLAS_GUI_ROUTE_AMENDMENT_DRAFT_PASS",after_proposal["generation"])
    assert next(p for p in stored if p["id"]==root_id)["items"][0]["estimateDays"]==2

    phase="gui-full-route-approval"
    activate_button("Решение")
    enter_editor_value("Почему принято это решение?",
                       "Human approved the explicit change after reviewing the impact")
    submit_editor()
    after_approval,stored=save_and_verify(lambda h,projects: any(
        c["id"]==proposed["id"] and c["status"]=="approved"
        for c in next(p for p in projects if p["id"]==root_id)["changes"]),
        "ATLAS_GUI_ROUTE_APPROVAL_PASS",after_amend["generation"])
    assert next(p for p in stored if p["id"]==root_id)["items"][0]["estimateDays"]==2

    phase="gui-full-route-apply"
    activate_button("Сценарий до / после")
    activate_button("Применить утверждённый план")
    keyboard.send_keys("{ENTER}")
    time.sleep(.4)
    applied_head,stored=save_and_verify(lambda h,projects:
        next(p for p in projects if p["id"]==root_id)["items"][0]["estimateDays"]==6,
        "ATLAS_GUI_ROUTE_PLAN_APPLIED_PASS",after_approval["generation"])
    root_final=next(p for p in stored if p["id"]==root_id)
    assert root_final["changes"][0].get("planAppliedAt")
    assert any(d.get("kind")=="plan_application" for d in root_final["decisions"])
    assert len(stored)==2 and any(x["id"]==baseline_route["projects"][1]["id"] for x in stored)
    shot("route-applied")
    stop()
    phase="gui-full-route-restart"
    boot()
    final_head,final_projects=native_data()
    assert final_head["generation"]==applied_head["generation"]
    assert sorted(p["id"] for p in final_projects)==route_ids
    assert next(p for p in final_projects if p["id"]==root_id)["items"][0]["estimateDays"]==6
    print("ATLAS_INSTALLED_G11_GUI_RESTART_PASS projects=2",flush=True)
    stop()
except Exception as exc:
    print("ATLAS_INSTALLED_LEGACY_01_GUI_HOLD phase="+phase+" reason="+repr(exc),flush=True)
    shot("failure")
    raise
finally:
    if process and process.poll() is None:
        process.kill()
        process.wait(timeout=10)
